FONTES_SEG = ['Norkin e White. Medida do movimento articular: manual de goniometria.', 'Hartmann, Wirth e Klusemann (2013), Sports Med: análise da carga no joelho e na coluna em diferentes profundidades de agachamento.',
  'Wilk et al. (2021), IJSPT: extensão de joelho em cadeia aberta após reconstrução do LCA (maior tensão no LCA entre 40° e 0°).', 'Fry, Smith e Schilling (2003), J Strength Cond Res: posição do joelho e torques no agachamento.',
  'Neumann. Cinesiologia do aparelho musculoesquelético.', 'Escamilla (2001), Med Sci Sports Exerc: biomecânica do joelho no agachamento.']
def seg_html(k):
    s = SEG[k]
    h = '<h3>Amplitude e segurança</h3><table class="ac"><tr><th>Movimento</th><th>Amplitude de referência</th></tr>' + ''.join(f'<tr><td><b>{m}</b></td><td>{v}</td></tr>' for m, v in s['amplitude']) + '</table>'
    h += '<h3>Onde as estruturas são mais exigidas</h3>' + ''.join(f'<div class="zona"><b>{t}</b><br>{x}</div>' for t, x in s['zonas'])
    h += f'<h3>Na prática</h3><p>{s["pratica"]}</p><div class="aviso">Não existe um ângulo que, sozinho, causa ou evita lesões: o que mais pesa é a carga em relação à capacidade dos tecidos, a progressão e o histórico da pessoa. As faixas acima ajudam a escolher e adaptar exercícios.</div>'
    h += '<div class="fontes">Fontes: ' + ' · '.join(FONTES_SEG) + '</div>'
    return h

